"use client";

import {
  RiAddLine,
  RiArrowDownSLine,
  RiArrowDropDownLine,
  RiArrowUpLine,
  RiAttachment2,
  RiCheckLine,
  RiFocus3Line,
  RiFolder2Line,
  RiGitMergeLine,
  RiInfinityLine,
  RiListCheck3,
  RiMic2Line,
  RiStopFill,
} from "@remixicon/react";
import { AnimatePresence, motion } from "motion/react";
import { type CSSProperties, type ReactNode, type Ref, useImperativeHandle, useEffect, useId, useMemo, useRef, useState } from "react";
import {
  Dropdown,
  DropdownDivider,
  DropdownGroup,
  DropdownItem,
  DropdownPopover,
  DropdownTrigger,
} from "../../base/dropdown/dropdown";
import { InputBase, TextField } from "../../base/input/input";
import { Button } from "../../base/buttons/button";
import { IconButton } from "../../base/buttons/icon-button";
import { EffortControl } from "../../base/slider/effort-control";
import { RadioDot } from "../../base/radio/radio";
import { cx } from "../../utils/cx";
import { PermissionMenu, type ComposerPermission } from "./permission-menu";
export type { ComposerPermission } from "./permission-menu";
import { CardSurface } from "../charts/card-surface";
import { Textarea } from "../../base/textarea/textarea";
import { ModelPicker, type ModelProvider } from "./model-picker";
import { composerProviders } from "./composer-providers";
import { ComposerStatusTab } from "./composer-status-tab";
import { ComposerAttachmentStrip, type ComposerAttachment } from "./composer-attachment-strip";
import { ContextMeter } from "./context-meter";
import { AgentThinking } from "../agent-thinking/agent-thinking";
import { ComposerLoader } from "../composer-loader/composer-loader";

export interface ComposerModel {
  id: string;
  label: string;
}
export interface ComposerProps {
  layout?: "pill" | "panel";
  expandedOnMobile?: boolean;
  permissionLabel?: string;
  permission?: ComposerPermission;
  onPermissionChange?: (permission: ComposerPermission) => void;
  onPermissionHelp?: () => void;
  value?: string;
  onValueChange?: (value: string) => void;
  onSubmit?: (value: string) => void;
  onStop?: () => void;
  busy?: boolean;
  model?: string;
  models?: ComposerModel[];
  onModelChange?: (model: string) => void;
  onFilesChange?: (files: File[]) => void;
  onToolSelect?: (tool: string) => void;
  /** Opt into removable selected-tool chips; tool actions otherwise dismiss the menu. */
  showToolSelection?: boolean;
  onVoiceToggle?: (listening: boolean) => void;
  placeholder?: string;
  className?: string;
}
export interface ComposerPanelProps extends ComposerProps {
  providers?: readonly ModelProvider[];
  defaultModel?: string;
  defaultPermission?: ComposerPermission;
  effort?: number;
  defaultEffort?: number;
  onEffortChange?: (effort: number) => void;
  status?: ReactNode | null;
  attachments?: ReactNode | readonly ComposerAttachment[];
  onRemoveAttachment?: (id: string) => void;
  surfaceClassName?: string;
  disabled?: boolean;
  inputRef?: Ref<HTMLTextAreaElement>;
  learnMoreHref?: string;
  onLearnMore?: () => void;
}
interface PanelComposition extends Omit<ComposerPanelProps, keyof ComposerProps> {
  providers: readonly ModelProvider[];
}
export interface StatusBarProps {
  branch?: string;
  onBranchPress?: () => void;
  project?: string;
  mode?: string;
  onModeChange?: (mode: string) => void;
  /** Allow the optional mode menu without a change callback. */
  enableModeSelection?: boolean;
  contextPercent?: number;
  folders?: string[];
  className?: string;
}
export const COMPOSER_MODELS: ComposerModel[] = [
  { id: "composer-2.5", label: "Model 1" },
  { id: "gpt-5.6-sol", label: "Model 2" },
  { id: "fable-5", label: "Model 3" },
  { id: "sonnet-5", label: "Model 4" },
];
const PLUGINS = [
  {
    id: "documents",
    label: "Documents",
    note: "Create and edit documents",
    asset: "/ai-chat/plugin-documents.svg",
  },
  {
    id: "spreadsheets",
    label: "Spreadsheets",
    note: "Generate spreadsheets",
    asset: "/ai-chat/plugin-spreadsheets.svg",
  },
  {
    id: "presentations",
    label: "Presentations",
    note: "Create marketing assets",
    asset: "/ai-chat/plugin-presentations.svg",
  },
  {
    id: "code",
    label: "Code blocks",
    note: "Write and edit existing code",
    asset: "/ai-chat/plugin-codeblocks.svg",
  },
];
function VoiceActivity({
  className,
  ...props
}: {
  className?: string;
  "aria-hidden"?: boolean | "true" | "false";
}) {
  return (
    <span
      {...props}
      className={cx("flex h-5 items-center justify-center gap-[2.5px]", className, "w-auto")}
    >
      {[
        [8, 0.9, -0.4],
        [15, 0.7, -0.15],
        [11, 1.05, -0.6],
        [14, 0.8, -0.3],
      ].map(([height, duration, delay], i) => (
        <span
          key={i}
          className="bui-composer-mic-bar w-[2.5px] rounded-full bg-accent-500"
          style={{
            height,
            animationDuration: `${duration}s`,
            animationDelay: `${delay}s`,
          }}
        />
      ))}
    </span>
  );
}
const GLASS_STYLE: CSSProperties = {
  background: "color-mix(in srgb, var(--color-background-primary-default) 14%, transparent)",
  backdropFilter: "blur(3px) saturate(1.45)",
  boxShadow:
    "inset 0 1px 1px color-mix(in srgb, var(--color-control-indicator-background) 90%, transparent), inset 0 -1px 2px color-mix(in srgb, var(--color-text-primary) 14%, transparent), 0 3px 8px color-mix(in srgb, var(--color-text-primary) 8%, transparent)",
};
const GLASS_CONTROL_STYLE: CSSProperties = {
  transition: "background-color 0.48s ease, border-color 0.48s ease, box-shadow 0.48s ease",
};
function GlassSurface({
  active,
  children,
  className,
  enabled = true,
}: {
  enabled?: boolean;
  active: boolean;
  children: ReactNode;
  className?: string;
}) {
  if (!enabled) return <>{children}</>;
  return (
    <span
      className={cx(
        "relative inline-flex shrink-0 items-center justify-center rounded-full",
        className,
      )}
    >
      <motion.span
        aria-hidden
        initial={false}
        animate={{ opacity: active ? 1 : 0, scale: active ? 1 : 0.94 }}
        transition={{ duration: 0.45, ease: [0.22, 1, 0.36, 1] }}
        className="pointer-events-none absolute inset-0 rounded-[inherit]"
        style={GLASS_STYLE}
      >
        <span className="landing-glass-stroke" />
      </motion.span>
      <span className="relative inline-flex items-center justify-center">{children}</span>
    </span>
  );
}

function ComposerPill({
  layout = "pill",
  expandedOnMobile = false,
  permissionLabel,
  permission: controlledPermission,
  onPermissionChange,
  onPermissionHelp,
  value: controlled,
  onValueChange,
  onSubmit,
  onStop,
  busy = false,
  model: controlledModel,
  models = COMPOSER_MODELS,
  onModelChange,
  onFilesChange,
  onToolSelect,
  showToolSelection = false,
  onVoiceToggle,
  placeholder,
  className,
  glass = false,
  glassEffects = false,
  panel,
}: ComposerProps & { glass?: boolean; glassEffects?: boolean; panel?: PanelComposition }) {
  const [input, setInput] = useState("");
  const [permission, setPermission] = useState<ComposerPermission>(panel?.defaultPermission ?? "bypass");
  const selectedPermission = controlledPermission ?? permission;
  const [model, setModel] = useState(panel?.defaultModel ?? "fable-5");
  const [attachmentOpen, setAttachmentOpen] = useState(false);
  const [modelOpen, setModelOpen] = useState(false);
  const [effort, setEffort] = useState(panel?.defaultEffort ?? 1);
  const selectedEffort = panel?.effort ?? effort;
  const [listening, setListening] = useState(false);
  const [attachments, setAttachments] = useState<string[]>([]);
  const [tool, setTool] = useState<string | null>(null);
  const [compactPlaceholder, setCompactPlaceholder] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);
  const panelFieldRef = useRef<HTMLTextAreaElement>(null);
  useImperativeHandle(panel?.inputRef, () => panelFieldRef.current!, []);
  const inputId = useId();
  const showFileChips = panel?.attachments === undefined;
  const value = controlled ?? input;
  const selectedModel = controlledModel ?? model;
  const modelLabel = models.find((item) => item.id === selectedModel)?.label ?? selectedModel;
  useEffect(() => {
    if (typeof window.matchMedia !== "function") return;
    const query = window.matchMedia("(max-width: 639px)");
    const updatePlaceholder = () => setCompactPlaceholder(query.matches);
    updatePlaceholder();
    query.addEventListener("change", updatePlaceholder);
    return () => query.removeEventListener("change", updatePlaceholder);
  }, []);
  useEffect(() => {
    const field = panelFieldRef.current;
    if (!field || layout !== "panel") return;
    const resize = () => {
      if (field.clientWidth === 0) return;
      field.style.height = "auto";
      const minimum = expandedOnMobile && window.matchMedia("(max-width:639px)").matches ? 200 : 20;
      field.style.height = `${Math.min(200, Math.max(minimum, field.scrollHeight))}px`;
    };
    resize();
    let width = field.clientWidth;
    const observer = new ResizeObserver((entries) => {
      const next = entries[0]?.contentRect.width;
      if (next !== undefined && next !== width) {
        width = next;
        resize();
      }
    });
    observer.observe(field);
    return () => observer.disconnect();
  }, [value, layout, expandedOnMobile]);
  function update(value: string) {
    if (controlled === undefined) setInput(value);
    onValueChange?.(value);
  }
  function submit() {
    if (!value.trim() || busy || panel?.disabled || !onSubmit) return;
    onSubmit?.(value.trim());
    if (controlled === undefined) setInput("");
  }
  function chooseTool(id: string) {
    setTool(id);
    setAttachmentOpen(false);
    onToolSelect?.(id);
  }
  const glassControl = glass && "border-transparent! bg-transparent! shadow-none!";
  const glassControlStyle = glassEffects ? GLASS_CONTROL_STYLE : undefined;
  const fileInput = (
    <input
      ref={fileRef}
      type="file"
      multiple
      className="hidden"
      aria-label="Attach files"
      onChange={(event) => {
        const files = Array.from(event.target.files ?? []);
        setAttachments((names) => [...names, ...files.map((file) => file.name)]);
        onFilesChange?.(files);
        event.target.value = "";
      }}
    />
  );
  const attachmentControl = (
    <Dropdown isOpen={attachmentOpen} onOpenChange={setAttachmentOpen}>
      <GlassSurface enabled={glassEffects} active={glass}>
        <DropdownTrigger
          aria-label="Add attachment"
          style={glassControlStyle}
          className={cx(
            "flex size-9 shrink-0 items-center justify-center rounded-full p-2 transition-colors duration-150",
            layout === "panel"
              ? "bg-composer-panel-add-background hover:bg-composer-panel-add-hover-background"
              : "bg-ai-chat-composer-add-background hover:bg-ai-chat-composer-add-hover-background",
            glassControl,
          )}
        >
          <RiAddLine
            aria-hidden
            className={cx(
              "size-5 text-foreground-icon-primary transition-transform duration-200",
              attachmentOpen && "rotate-45",
            )}
          />
        </DropdownTrigger>
      </GlassSurface>
      <DropdownPopover
        aria-label="Add attachment or tool"
        placement="top start"
        offset={8}
        className="w-[361px] p-2"
        dialogClassName="gap-2"
      >
        <DropdownGroup label="Add">
          <DropdownItem
            className="px-2 py-1.5"
            onSelect={() => {
              setAttachmentOpen(false);
              fileRef.current?.click();
            }}
          >
            <RiAttachment2 className="size-5 shrink-0 text-foreground-icon-secondary" />
            <span className="truncate text-body-medium whitespace-nowrap">Files and folders</span>
          </DropdownItem>
          <DropdownItem className="px-2 py-1.5" onSelect={() => chooseTool("Goal")}>
            <RiFocus3Line className="size-5 shrink-0 text-foreground-icon-secondary" />
            <span className="truncate text-body-medium whitespace-nowrap">
              <span>Goal</span>
              <span className="ml-1.5 text-text-secondary">Set a goal for faster results</span>
            </span>
          </DropdownItem>
          <DropdownItem className="px-2 py-1.5" onSelect={() => chooseTool("Plan mode")}>
            <RiListCheck3 className="size-5 shrink-0 text-foreground-icon-secondary" />
            <span className="truncate text-body-medium whitespace-nowrap">
              <span>Plan mode</span>
              <span className="ml-1.5 text-text-secondary">Manage complex tasks</span>
            </span>
          </DropdownItem>
        </DropdownGroup>
        <DropdownGroup label="Plugins">
          {PLUGINS.map((plugin) => (
            <DropdownItem
              key={plugin.id}
              onSelect={() => chooseTool(plugin.label)}
              className="px-2 py-1.5"
            >
              <img
                src={plugin.asset}
                alt=""
                aria-hidden
                className={cx("size-6 shrink-0", plugin.id === "documents" && "dark:hidden")}
              />
              {plugin.id === "documents" && (
                <img
                  src="/ai-chat/plugin-documents-dark.svg"
                  alt=""
                  aria-hidden
                  className="hidden size-6 shrink-0 dark:block"
                />
              )}
              <span className="truncate text-body-medium whitespace-nowrap text-text-primary">
                {plugin.label}
                <span className="ml-1.5 text-text-secondary">{plugin.note}</span>
              </span>
            </DropdownItem>
          ))}
        </DropdownGroup>
      </DropdownPopover>
    </Dropdown>
  );
  const panelField = (
    <Textarea
      ref={panelFieldRef}
      disabled={panel?.disabled}
      rows={1}
      aria-label="Message"
      value={value}
      onChange={(e) => update(e.target.value)}
      placeholder={placeholder ?? "Hi, what do you need today?"}
      onKeyDown={(e) => {
        if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
          e.preventDefault();
          submit();
        }
      }}
      className={cx(
        "block h-5 min-h-0 max-h-[200px] w-full resize-none rounded-none bg-transparent p-0 focus-visible:ring-0 text-body-regular text-text-primary caret-accent-500 outline-none placeholder:text-text-tertiary",
        expandedOnMobile && "h-[200px] sm:h-5",
      )}
    />
  );
  const pillField = (
    <TextField
      aria-label="Message"
      value={value}
      onChange={update}
      className="min-w-0 flex-1"
      onKeyDown={(event) => {
        if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {
          event.preventDefault();
          submit();
        }
      }}
    >
      <InputBase
        id={inputId}
        placeholder={placeholder ?? (compactPlaceholder ? "Ask me" : "Ask me anything")}
        fieldClassName="rounded-none bg-transparent p-0 ring-0 focus-within:ring-0 shadow-none"
        className="h-5 pl-0 caret-accent-500 focus:placeholder:text-text-tertiary [&:not(:focus)]:[mask-image:linear-gradient(to_right,#000_calc(100%-32px),transparent_100%)]"
      />
    </TextField>
  );
  const permissionControl = (
    <PermissionMenu value={selectedPermission} label={permissionLabel}
      onChange={(next) => { setPermission(next); onPermissionChange?.(next); }}
      learnMoreHref={panel?.learnMoreHref}
      onLearnMore={panel?.onLearnMore ?? onPermissionHelp} />
  );
  const modelControl = panel ? (
    <ModelPicker providers={panel.providers} value={selectedModel}
      onChange={(next) => { setModel(next); onModelChange?.(next); }}
      effort={selectedEffort} onEffortChange={(next) => { setEffort(next); panel.onEffortChange?.(next); }} />
  ) : (
    <Dropdown isOpen={modelOpen} onOpenChange={setModelOpen}>
      <GlassSurface enabled={glassEffects} active={glass} className="rounded-xl">
        <DropdownTrigger
          aria-label={`Select model: ${modelLabel}`}
          style={glassControlStyle}
          className={cx(
            "flex h-8 shrink-0 items-center justify-center gap-0.5 rounded-xl bg-background-primary-default py-1.5 pr-1 pl-2 transition-colors duration-150 ease hover:bg-background-primary-hover",
            glassControl,
          )}
        >
          <span className="max-w-[110px] truncate px-0.5 text-body-medium text-text-secondary">
            {modelLabel}
          </span>
          <RiArrowDownSLine
            aria-hidden
            className={cx(
              "size-[18px] shrink-0 text-foreground-icon-secondary transition-transform duration-200 ease",
              modelOpen && "rotate-180",
            )}
          />
        </DropdownTrigger>
      </GlassSurface>
      <DropdownPopover
        aria-label="Models and effort"
        placement="top start"
        offset={8}
        className="w-[266px]"
        dialogClassName="gap-0"
      >
        <DropdownGroup label="Models">
          <div role="radiogroup" aria-label="Model" className="flex flex-col gap-1">
            {models.map((item) => (
              <Button
                unstyled
                type="button"
                role="radio"
                key={item.id}
                aria-checked={item.id === selectedModel}
                className={cx(
                  "flex w-full cursor-pointer items-center justify-between gap-2.5 rounded-2lg p-2 outline-none transition-colors hover:bg-background-primary-hover focus-visible:bg-background-primary-hover",
                  item.id === selectedModel && "bg-background-primary-hover",
                )}
                onClick={() => {
                  setModel(item.id);
                  onModelChange?.(item.id);
                  setModelOpen(false);
                }}
              >
                <span className="truncate text-body-medium whitespace-nowrap text-text-primary">
                  {item.label}
                </span>
                <RadioDot selected={item.id === selectedModel} />
              </Button>
            ))}
          </div>
        </DropdownGroup>
        <DropdownDivider className="mt-[7px] mb-3" />
        <EffortControl value={effort} onChange={setEffort} />
      </DropdownPopover>
    </Dropdown>
  );
  const voiceControls = (
    <div className={cx("flex shrink-0 items-center gap-2 pl-1.5", layout === "panel" && "pl-0")}>
      <GlassSurface enabled={glassEffects} active={glass}>
        <IconButton
          unstyled
          icon={listening ? VoiceActivity : RiMic2Line}
          size="medium"
          aria-label="Voice input"
          style={glassControlStyle}
          aria-pressed={listening}
          onClick={() => {
            setListening(!listening);
            onVoiceToggle?.(!listening);
          }}
          className={cx(
            "flex size-9 cursor-pointer items-center justify-center rounded-full border border-border-button-default bg-background-primary-default p-2 text-foreground-icon-primary shadow-xs transition-colors duration-150 ease hover:bg-background-primary-hover [&_svg]:shrink-0",
            glassControl,
          )}
        />
      </GlassSurface>
      <IconButton
        unstyled
        icon={busy ? RiStopFill : RiArrowUpLine}
        size="medium"
        aria-label={busy ? "Stop generating" : "Send message"}
        onClick={busy ? onStop : submit}
        disabled={panel?.disabled && !busy}
        className={cx(
          "flex size-9 cursor-pointer items-center justify-center rounded-full bg-button-primary p-2 transition-opacity duration-200 ease [@media(hover:none)]:before:opacity-0!",
          !glass && (panel ? "[&_svg]:text-text-white" : "text-text-white"),
          glass && "bg-transparent! text-foreground-icon-primary",
        )}
      />
    </div>
  );
  return (
    <div className={cx("relative w-full", panel && "flex max-w-[699px] flex-col", className)}>
      {panel && (panel.status === undefined ? <ComposerStatusTab /> : panel.status)}
      <AnimatePresence>
        {((showToolSelection && tool) || (showFileChips && attachments.length > 0)) && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            className="flex flex-wrap gap-1.5 overflow-hidden pb-2"
          >
            {[
              ...(showToolSelection && tool ? [{ name: tool, isTool: true }] : []),
              ...(showFileChips ? attachments.map((name) => ({ name, isTool: false })) : []),
            ].map(({ name, isTool }, index) => (
              <Button
                unstyled
                type="button"
                key={`${index}-${name}`}
                onClick={() => {
                  if (isTool) setTool(null);
                  else setAttachments((names) => names.filter((item) => item !== name));
                }}
                aria-label={`Remove ${name}`}
                className="rounded-md bg-background-secondary-default px-2 py-1 text-caption-1-medium text-text-secondary"
              >
                {name} <span aria-hidden>×</span>
              </Button>
            ))}
          </motion.div>
        )}
      </AnimatePresence>
      {fileInput}
      {layout === "panel" ? (
        <CardSurface tone="primary" padding="inset" className={cx("flex w-full flex-col rounded-[22px] shadow-[0_1px_0.5px_rgba(0,0,0,0.02),0_4px_2px_rgba(0,0,0,0.02)]", panel && "rounded-3xl", panel?.surfaceClassName)}>
          {Array.isArray(panel?.attachments) && panel.attachments.every(file => file && typeof file === "object" && "id" in file && "kind" in file && "name" in file)
            ? <ComposerAttachmentStrip attachments={panel.attachments as ComposerAttachment[]} onRemove={panel.onRemoveAttachment} />
            : panel?.attachments as ReactNode}
          <div className="flex flex-col gap-5 pt-1.5">
            <div className="px-1.5">{panelField}</div>
            <div className={cx("flex items-center justify-between gap-2", panel && "flex-wrap")}>
              <div className="flex min-w-0 items-center gap-2">
                {attachmentControl}
                {permissionControl}
              </div>
              <div className="flex shrink-0 items-center gap-4">
                {modelControl}
                {voiceControls}
              </div>
            </div>
          </div>
        </CardSurface>
      ) : (
        <div
          className={cx(
            "relative flex h-[52px] w-full items-center gap-2.5 rounded-full p-2",
            glass ? "bg-transparent" : "bg-background-primary-default shadow-xs",
          )}
        >
          {attachmentControl}
          {pillField}
          {modelControl}
          {voiceControls}
        </div>
      )}
    </div>
  );
}

export function ComposerPanel({
  providers, defaultModel, defaultPermission = "auto", defaultEffort = 1,
  effort, onEffortChange, status, attachments, onRemoveAttachment, surfaceClassName, disabled,
  inputRef, learnMoreHref, onLearnMore, ...props
}: ComposerPanelProps = {}) {
  const choices = useMemo(() => providers ?? composerProviders(props.models), [providers, props.models]);
  const initialModel = defaultModel ?? (props.models
    ? props.models.find((model) => model.id === "fable-5")?.id ?? props.models[0]?.id
    : "compact-model");
  return <ComposerPill {...props} layout="panel" panel={{
    providers: choices, defaultModel: initialModel, defaultPermission, defaultEffort,
    effort, onEffortChange, status, attachments, onRemoveAttachment, surfaceClassName, disabled,
    inputRef, learnMoreHref, onLearnMore,
  }} />;
}

export function Composer(props: ComposerProps = {}) {
  return <ComposerPill {...props} />;
}
export function GlassComposer({
  glass = false,
  ...props
}: ComposerProps & { glass?: boolean } = {}) {
  return <ComposerPill {...props} glass={glass} glassEffects />;
}

export function StatusBar({
  branch = "Main",
  onBranchPress,
  project: controlledProject = "app",
  folders = ["workspace/projects/app", "workspace/desktop/gallery", "workspace/documents/ui"],
  mode: controlledMode,
  onModeChange,
  enableModeSelection = !!onModeChange,
  contextPercent = 57,
  className,
}: StatusBarProps = {}) {
  const [project, setProject] = useState(controlledProject);
  const [mode, setMode] = useState("Agent");
  const [folderOpen, setFolderOpen] = useState(false);
  const [modeOpen, setModeOpen] = useState(false);
  const percent = Math.max(0, Math.min(100, contextPercent));
  const activeMode = controlledMode ?? mode;
  const modeContent = (
    <>
      <RiInfinityLine className="size-4 text-foreground-icon-secondary" aria-hidden />
      <span className="flex items-center">
        <span className="text-body-2-medium whitespace-nowrap text-text-secondary">
          {activeMode}
        </span>
        <RiArrowDropDownLine className="size-4 text-foreground-icon-secondary" aria-hidden />
      </span>
    </>
  );
  return (
    <div className={cx("flex h-[26px] w-full items-center justify-between gap-2", className)}>
      <div className="flex min-w-0 items-center gap-3">
        <Button
          unstyled
          type="button"
          onClick={onBranchPress}
          className="flex cursor-pointer items-center gap-1"
        >
          <RiGitMergeLine
            className="size-4 shrink-0 -scale-y-100 text-foreground-icon-secondary"
            aria-hidden
          />
          <span className="flex items-center">
            <span className="whitespace-nowrap text-body-2-medium text-text-secondary">
              {branch}
            </span>
          </span>
        </Button>
        <Dropdown isOpen={folderOpen} onOpenChange={setFolderOpen}>
          <DropdownTrigger className="flex min-w-0 items-center gap-1 rounded-sm">
            <RiFolder2Line className="size-4 shrink-0 text-foreground-icon-secondary" aria-hidden />
            <span className="flex min-w-0 items-center">
              <span className="max-w-[150px] truncate text-body-2-medium text-text-secondary">
                {project}
              </span>
              <RiArrowDropDownLine
                className={cx(
                  "size-4 shrink-0 text-foreground-icon-secondary transition-transform duration-200 ease",
                  folderOpen && "rotate-180",
                )}
                aria-hidden
              />
            </span>
          </DropdownTrigger>
          <DropdownPopover
            aria-label="Local folders"
            placement="top start"
            offset={8}
            className="w-[266px]"
          >
            <DropdownGroup label="Local Folders">
              {folders.map((folder) => (
                <DropdownItem
                  key={folder}
                  selected={folder.endsWith(`/${project}`)}
                  onSelect={() => {
                    setProject(folder.split("/").pop() ?? folder);
                    setFolderOpen(false);
                  }}
                >
                  <RiFolder2Line className="size-5 shrink-0 text-foreground-icon-secondary" />
                  <span className="truncate text-body-medium whitespace-nowrap">
                    <span className="text-text-secondary">
                      {folder.slice(0, folder.lastIndexOf("/") + 1)}
                    </span>
                    <span className="text-text-primary">{folder.split("/").pop()}</span>
                  </span>
                </DropdownItem>
              ))}
            </DropdownGroup>
          </DropdownPopover>
        </Dropdown>
      </div>
      <div className="flex shrink-0 items-center gap-3">
        <Dropdown isOpen={modeOpen} onOpenChange={setModeOpen}>
          {enableModeSelection ? (
            <DropdownTrigger className="flex items-center gap-1 rounded-sm">
              {modeContent}
            </DropdownTrigger>
          ) : (
            <Button unstyled className="flex items-center gap-1 rounded-sm outline-none">
              {modeContent}
            </Button>
          )}
          <DropdownPopover aria-label="Agent mode" placement="top end" className="w-[180px]">
            {["Agent", "Ask", "Plan"].map((value) => (
              <DropdownItem
                key={value}
                selected={value === activeMode}
                onSelect={() => {
                  setMode(value);
                  onModeChange?.(value);
                  setModeOpen(false);
                }}
              >
                <span className="flex-1">{value}</span>
                {value === activeMode && <RiCheckLine className="size-4" />}
              </DropdownItem>
            ))}
          </DropdownPopover>
        </Dropdown>
        <ContextMeter percent={percent} />
      </div>
    </div>
  );
}

export function AiChatComposerPreview({ busy: controlledBusy, ...props }: ComposerProps = {}) {
  const [busy, setBusy] = useState(false);
  const active = controlledBusy ?? busy;
  useEffect(() => {
    if (!busy || controlledBusy !== undefined) return;
    const timer = window.setTimeout(() => setBusy(false), 4500);
    return () => window.clearTimeout(timer);
  }, [busy, controlledBusy]);
  return (
    <div className="flex w-full max-w-[560px] flex-col gap-2.5">
      <AnimatePresence>
        {active && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
          >
            <AgentThinking variant="infinity" />
          </motion.div>
        )}
      </AnimatePresence>
      <div className="relative">
        <span
          aria-hidden
          className="pointer-events-none absolute inset-0 rounded-full bg-text-primary opacity-10 blur-[50px] dark:hidden"
        />
        <ComposerLoader active={active} surface={active}>
          <GlassComposer
            {...props}
            busy={active}
            glass={active}
            onSubmit={(value) => {
              props.onSubmit?.(value);
              if (controlledBusy === undefined) setBusy(true);
            }}
            onStop={() => {
              props.onStop?.();
              setBusy(false);
            }}
          />
        </ComposerLoader>
      </div>
      <StatusBar />
    </div>
  );
}

/** A draft composer with its status controls; submission belongs to the consuming app. */
export function ComposerPreview({
