        <span
          aria-hidden
          className="pointer-events-none absolute inset-0 rounded-full bg-black opacity-10 blur-[50px] dark:hidden"
        />
        <Composer {...props} />
      </div>
      <StatusBar {...status} />
    </div>
  );
}
